use std::{
    fs, io,
    path::{Component, Path},
};

use serde::Serialize;

use crate::{console::generator_command::write_generated, support::ServiceProvider};

/// A package selected from the application's linked Cargo dependencies.
pub struct DiscoveredPackage {
    pub name: &'static str,
    pub version: &'static str,
    pub library: &'static str,
    pub aliases: &'static [(&'static str, &'static str)],
    providers: fn() -> Vec<Box<dyn ServiceProvider>>,
}

impl DiscoveredPackage {
    pub const fn new(
        name: &'static str,
        version: &'static str,
        library: &'static str,
        aliases: &'static [(&'static str, &'static str)],
        providers: fn() -> Vec<Box<dyn ServiceProvider>>,
    ) -> Self {
        Self {
            name,
            version,
            library,
            aliases,
            providers,
        }
    }
}

/// The package catalog generated by the application's Cargo build.
#[derive(Clone, Copy, Default)]
pub struct PackageManifest(
    &'static [DiscoveredPackage],
    &'static [crate::view::NativeTemplate],
);

#[derive(Serialize)]
struct Record {
    name: &'static str,
    version: &'static str,
    library: &'static str,
    aliases: &'static [(&'static str, &'static str)],
}

impl PackageManifest {
    pub const fn new(packages: &'static [DiscoveredPackage]) -> Self {
        Self(packages, &[])
    }

    /// 构建产物与包清单一同装配，避免另建运行期注册入口。
    pub const fn with_native_views(
        mut self,
        templates: &'static [crate::view::NativeTemplate],
    ) -> Self {
        self.1 = templates;
        self
    }

    pub(crate) fn native_views(self) -> &'static [crate::view::NativeTemplate] {
        self.1
    }

    pub fn packages(self) -> &'static [DiscoveredPackage] {
        self.0
    }

    pub(super) fn providers(self) -> Vec<Box<dyn ServiceProvider>> {
        self.0
            .iter()
            .flat_map(|package| (package.providers)())
            .collect()
    }

    fn contents(self) -> io::Result<Vec<u8>> {
        let packages = self
            .0
            .iter()
            .map(|entry| Record {
                name: entry.name,
                version: entry.version,
                library: entry.library,
                aliases: entry.aliases,
            })
            .collect::<Vec<_>>();
        let mut bytes = serde_json::to_vec_pretty(&packages)?;
        bytes.push(b'\n');
        Ok(bytes)
    }

    pub(super) fn rebuild(self, root: &Path, path: &Path) -> io::Result<()> {
        validate_parent(root, path)?;
        regular_file_exists(path)?;
        write_generated(path, &self.contents()?, true)
    }

    pub(super) fn clear(root: &Path, path: &Path) -> io::Result<()> {
        validate_parent(root, path)?;
        if regular_file_exists(path)? {
            match fs::remove_file(path) {
                Err(error) if error.kind() == io::ErrorKind::NotFound => (),
                result => result?,
            }
        }
        Ok(())
    }
}

fn validate_parent(root: &Path, path: &Path) -> io::Result<()> {
    let Some(parent) = path.parent() else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "invalid package cache path",
        ));
    };
    let Ok(relative) = parent.strip_prefix(root) else {
        return Ok(());
    };
    let mut directory = root.to_owned();
    for component in relative.components() {
        let Component::Normal(name) = component else {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "invalid package cache path",
            ));
        };
        directory.push(name);
        match fs::symlink_metadata(&directory) {
            Ok(metadata) if metadata.is_dir() => (),
            Ok(_) => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!(
                        "package cache parent must be a directory: {}",
                        directory.display()
                    ),
                ));
            }
            Err(error) if error.kind() == io::ErrorKind::NotFound => (),
            Err(error) => return Err(error),
        }
    }
    Ok(())
}

fn regular_file_exists(path: &Path) -> io::Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_file() => Ok(true),
        Ok(_) => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("package cache must be a regular file: {}", path.display()),
        )),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error),
    }
}
